<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Reports</h2><p class="text-muted">Inventory and circulation activity.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-dark" href="<?= BASE_URL ?>/?page=reports&action=pdf">Export PDF</a><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=reports&action=csv">Export CSV</a></div></div><div class="card p-3"><table class="table"><thead><tr><th>Book</th><th>Borrower</th><th>Checked out</th><th>Due</th><th>Returned</th><th>Status</th><th>Fine</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= Security::e($r['title']) ?></td><td><?= Security::e($r['borrower_name']) ?></td><td><?= Security::e($r['checked_out_at']) ?></td><td><?= Security::e($r['due_date']) ?></td><td><?= Security::e($r['returned_at']??'—') ?></td><td><?= Security::e(ucwords(str_replace('_',' ',$r['status']))) ?></td><td>₱<?= number_format((float)$r['fine'],2) ?></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
